import type {
  LegacyStorage,
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  ReservationEvent,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import {
  decodeCanonicalDecimal,
  decodeReservation,
  decodeStock,
  encodeCanonicalDecimal,
  isId,
  isQuantity,
  isRecord,
  isRevision,
  isUnits,
} from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

export function error(status: 400 | 404 | 409 | 500, code: string): ServiceResponse {
  return { status, body: { code } };
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

type ReservationLookup =
  | Readonly<{ kind: "Found"; reservation: Reservation }>
  | Readonly<{ kind: "Missing" }>
  | Readonly<{ kind: "Unavailable" }>;

type StockLookup =
  | Readonly<{ kind: "Found"; stock: Stock }>
  | Readonly<{ kind: "Missing" }>
  | Readonly<{ kind: "Unavailable" }>;

type CommitOutcome = "committed" | "revision_conflict" | "unavailable";

type ReservationBackend = Readonly<{
  getStock: (sku: string) => Promise<StockLookup>;
  getReservation: (reservationId: string) => Promise<ReservationLookup>;
  commitReservation: (stock: Stock, reservation: Reservation, event: ReservationEvent) => Promise<CommitOutcome>;
}>;

function createReservationServiceWithBackend(backend: ReservationBackend): Service {
  return {
    async handle(raw) {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        if (command.op === "getAvailability") {
          const lookup = await backend.getStock(command.sku);
          if (lookup.kind === "Missing") return error(404, "stock_not_found");
          if (lookup.kind === "Unavailable") return error(500, "storage_unavailable");
          const stock = lookup.stock;
          return {
            status: 200,
            body: {
              sku: stock.sku,
              totalUnits: stock.totalUnits,
              reservedUnits: stock.reservedUnits,
              availableUnits: stock.totalUnits - stock.reservedUnits,
            },
          };
        }

        const reservationLookup = await backend.getReservation(command.reservationId);
        if (reservationLookup.kind === "Unavailable") return error(500, "storage_unavailable");
        const existing = reservationLookup.kind === "Found" ? reservationLookup.reservation : undefined;
        if (command.op === "getReservation") {
          return existing ? reservationResponse(200, existing) : error(404, "reservation_not_found");
        }
        if (existing) {
          return existing.sku === command.sku && existing.quantity === command.quantity
            ? reservationResponse(200, existing)
            : error(409, "reservation_conflict");
        }

        const stockLookup = await backend.getStock(command.sku);
        if (stockLookup.kind === "Missing") return error(404, "stock_not_found");
        if (stockLookup.kind === "Unavailable") return error(500, "storage_unavailable");
        const stock = stockLookup.stock;
        if (stock.totalUnits - stock.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }
        const nextRevision = stock.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");
        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const event: ReservationEvent = {
          eventId: "reservation.created:" + reservation.reservationId,
          type: "reservation.created",
          reservationId: reservation.reservationId,
          sku: reservation.sku,
          quantity: reservation.quantity,
        };
        const outcome = await backend.commitReservation(stock, reservation, event);
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome === "unavailable") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

export function createReservationService({ storage }: { storage: LegacyStorage }): Service {
  return createReservationServiceWithBackend({
    getStock: async (sku) => {
      const rawStock = await storage.getStock(sku);
      if (rawStock === undefined) return { kind: "Missing" };
      const stock = decodeStock(rawStock);
      if (!stock || stock.sku !== sku) return { kind: "Unavailable" };
      return { kind: "Found", stock };
    },
    getReservation: async (reservationId) => {
      const rawReservation = await storage.getReservation(reservationId);
      if (rawReservation === undefined) return { kind: "Missing" };
      const reservation = decodeReservation(rawReservation);
      if (!reservation || reservation.reservationId !== reservationId) return { kind: "Unavailable" };
      return { kind: "Found", reservation };
    },
    commitReservation: async (stock, reservation, event) => {
      const nextRevision = stock.revision + 1;
      if (!isRevision(nextRevision)) return "unavailable";
      const outcome = await storage.commitReservation({
        expectedRevision: stock.revision,
        nextStock: {
          ...stock,
          reservedUnits: stock.reservedUnits + reservation.quantity,
          revision: nextRevision,
        },
        reservation,
        events: [event],
      });
      if (outcome === "revision_conflict") return "revision_conflict";
      return outcome === "committed" ? "committed" : "unavailable";
    },
  });
}

function decodeProviderBStockRow(value: unknown, key: string): Stock | undefined {
  if (!isRecord(value) || value.itemKey !== key) return undefined;
  const totalUnits = decodeCanonicalDecimal(value.onHandText);
  const reservedUnits = decodeCanonicalDecimal(value.heldText);
  const revision = decodeCanonicalDecimal(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined || revision === undefined ||
      !isUnits(totalUnits) || !isUnits(reservedUnits) || reservedUnits > totalUnits ||
      !isRevision(revision)) return undefined;
  return {
    sku: value.itemKey,
    totalUnits,
    reservedUnits,
    revision,
  };
}

function decodeProviderBReservationRow(value: unknown, key: string): Reservation | undefined {
  if (!isRecord(value) || value.bookingKey !== key || !isId(value.itemKey)) return undefined;
  const quantity = decodeCanonicalDecimal(value.unitsText);
  if (quantity === undefined || !isQuantity(quantity)) return undefined;
  return {
    reservationId: value.bookingKey,
    sku: value.itemKey,
    quantity,
  };
}

function readProviderBEnvelope(raw: unknown): "missing" | "unavailable" | unknown {
  if (!isRecord(raw) || typeof raw.ok !== "boolean") return "unavailable";
  if (raw.ok) return raw.value === undefined || raw.value === null ? "unavailable" : raw.value;
  if (!isRecord(raw.error)) return "unavailable";
  if (raw.error.reason === "NO_SUCH_KEY") return "missing";
  return "unavailable";
}

function providerBStockRow(stock: Stock, reservedUnits: number, revision: number): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: encodeCanonicalDecimal(stock.totalUnits),
    heldText: encodeCanonicalDecimal(reservedUnits),
    revisionText: encodeCanonicalDecimal(revision),
  };
}

function providerBReservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: encodeCanonicalDecimal(reservation.quantity),
  };
}

function providerBBatch(stock: Stock, reservation: Reservation): ProviderBCommitBatch | undefined {
  const nextRevision = stock.revision + 1;
  if (!isRevision(nextRevision)) return undefined;
  return {
    expectedRevisionText: encodeCanonicalDecimal(stock.revision),
    stockRow: providerBStockRow(stock, stock.reservedUnits + reservation.quantity, nextRevision),
    reservationRow: providerBReservationRow(reservation),
    outboxRows: [{
      key: "reservation.created:" + reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: reservation.reservationId,
        itemKey: reservation.sku,
        unitsText: encodeCanonicalDecimal(reservation.quantity),
      },
    }],
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return createReservationServiceWithBackend({
    getStock: async (sku) => {
      const envelope = readProviderBEnvelope(await storage.read({ collection: "inventory", key: sku }));
      if (envelope === "missing") return { kind: "Missing" };
      if (envelope === "unavailable") return { kind: "Unavailable" };
      const stock = decodeProviderBStockRow(envelope, sku);
      return stock ? { kind: "Found", stock } : { kind: "Unavailable" };
    },
    getReservation: async (reservationId) => {
      const envelope = readProviderBEnvelope(await storage.read({ collection: "reservations", key: reservationId }));
      if (envelope === "missing") return { kind: "Missing" };
      if (envelope === "unavailable") return { kind: "Unavailable" };
      const reservation = decodeProviderBReservationRow(envelope, reservationId);
      return reservation ? { kind: "Found", reservation } : { kind: "Unavailable" };
    },
    commitReservation: async (stock, reservation) => {
      const batch = providerBBatch(stock, reservation);
      if (!batch) return "unavailable";
      const outcome = await storage.commitBatch(batch);
      if (outcome === "revision_conflict") return "revision_conflict";
      if (outcome === "applied") return "committed";
      return "unavailable";
    },
  });
}

